package it.carmine.streamplayer;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.drawable.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Native RaiPlay catalogue and episode navigation, using R. ITA artwork and theme. */
public class RaiPlayActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private int generation;private boolean destroyed,history;private FrameLayout root;private LinearLayout rows;private TextView status;private EditText query;private ArtworkStore artwork;private RaiCatalogLoader loader;private VodSource.Title selected;private final Deque<String> back=new ArrayDeque<>();private String page="",pageLabel="";private JSONArray episodeQueue=new JSONArray();
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(UiTheme.TEXT);t.setTypeface(UiTheme.medium(this));return t;}private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);UiTheme.navigation(b);return b;}
 public void onCreate(Bundle state){super.onCreate(state);history=getIntent().getBooleanExtra("history",false);VodNetwork.initialize(this);RaiAccount.init(this);getWindow().getDecorView().setSystemUiVisibility(5894);artwork=new ArtworkStore(this,true);root=new FrameLayout(this);root.setBackgroundColor(UiTheme.background(this));setContentView(root);LinearLayout body=new LinearLayout(this);body.setPadding(dp(24),dp(12),dp(24),dp(12));body.setOrientation(1);root.addView(body,new FrameLayout.LayoutParams(-1,-1));TextView title=text("RaiPlay",28);title.setTextColor(UiTheme.accent(this));body.addView(title);LinearLayout nav=new LinearLayout(this);body.addView(nav);for(String name:new String[]{"Catalogo","Continua a guardare","Account","‹ VOD"}){Button b=button(name);nav.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));b.setOnClickListener(v->{if(name.equals("Account")){startActivity(new Intent(this,RaiAccountActivity.class));return;}if(name.equals("‹ VOD")){finish();return;}back.clear();page="";if(name.equals("Catalogo"))query.setText("");history=name.equals("Continua a guardare");loadCatalogue();});}LinearLayout bar=new LinearLayout(this);body.addView(bar);query=VodSettings.input(this,"","Cerca su RaiPlay");query.setSingleLine(true);bar.addView(query,new LinearLayout.LayoutParams(0,dp(48),1));Button search=button("Cerca");bar.addView(search);search.setOnClickListener(v->{back.clear();page="";history=false;loadCatalogue();});status=text("",13);status.setTextColor(UiTheme.accent(this));body.addView(status);ScrollView scroll=new ScrollView(this);rows=new LinearLayout(this);rows.setOrientation(1);scroll.addView(rows);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(state!=null){try{episodeQueue=new JSONArray(state.getString("queue","[]"));}catch(Exception ignored){}history=state.getBoolean("history");query.setText(state.getString("query",""));page=state.getString("page","");pageLabel=state.getString("label","");ArrayList<String> stack=state.getStringArrayList("back");if(stack!=null)back.addAll(stack);try{selected=new VodSource.Title(new JSONObject(state.getString("title","{}")),"");}catch(Exception ignored){}}else try{String raw=getIntent().getStringExtra("titleJson");if(raw!=null){selected=new VodSource.Title(new JSONObject(raw),"");if(getIntent().getBooleanExtra("resume",false)){resume(selected);return;}page=selected.json.optString("_rai_page");pageLabel=selected.name;}}catch(Exception ignored){}if(!page.isEmpty())detail(page,pageLabel,false);else loadCatalogue();}
 private void cancel(){generation++;if(loader!=null){loader.close();loader=null;}}
 private void loadCatalogue(){cancel();rows.removeAllViews();if(history){List<VodSource.Title> saved=RaiLibrary.history(this);showTitles(saved,true);status.setText(saved.isEmpty()?"Nessun contenuto in Continua a guardare":"Continua a guardare · tieni premuto sul titolo per rimuoverlo");return;}int request=generation;status.setText("Caricamento catalogo RaiPlay…");loader=new RaiCatalogLoader(this,root);loader.load(query.getText().toString().trim(),(titles,error)->{if(destroyed||request!=generation)return;status.setText(error.isEmpty()?"RaiPlay · "+titles.size()+" titoli":error);showTitles(titles,false);});}
 private void showTitles(List<VodSource.Title> titles,boolean resume){rows.removeAllViews();int columns=getResources().getDisplayMetrics().widthPixels>=dp(700)?5:3;LinearLayout line=null;for(int i=0;i<titles.size();i++){if(i%columns==0){line=new LinearLayout(this);rows.addView(line);}VodSource.Title t=titles.get(i);LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(6),dp(6),dp(6),dp(8));card.setFocusable(true);card.setClickable(true);card.setBackground(background(false));card.setOnFocusChangeListener((v,f)->v.setBackground(background(f)));ProgrammeArtwork image=new ProgrammeArtwork(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(image,new LinearLayout.LayoutParams(-1,dp(190)));artwork.bind(image,t.poster,new ColorDrawable(UiTheme.panel(this)));TextView label=text(t.name,14);label.setMaxLines(2);card.addView(label);JSONObject h=VodLibrary.latest(this,"raiplay",t.id);if(h!=null){ProgressBar p=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);p.setProgress(VodLibrary.percent(h));p.setProgressTintList(android.content.res.ColorStateList.valueOf(UiTheme.accent(this)));card.addView(p,new LinearLayout.LayoutParams(-1,dp(5)));card.addView(text(VodLibrary.clock(h.optLong("position"))+" / "+VodLibrary.clock(h.optLong("duration")),12));}card.setOnClickListener(v->{selected=t;if(resume)resume(t);else detail(t.json.optString("_rai_page"),t.name,true);});if(resume){card.setOnLongClickListener(v->{RaiLibrary.confirmRemove(this,t,()->loadCatalogue());return true;});card.setOnKeyListener((v,key,event)->{if(key!=KeyEvent.KEYCODE_MENU)return false;if(event.getAction()==KeyEvent.ACTION_UP)RaiLibrary.confirmRemove(this,t,()->loadCatalogue());return true;});}line.addView(card,new LinearLayout.LayoutParams(getResources().getDisplayMetrics().widthPixels/columns-dp(18),-2));}if(rows.getChildCount()>0)rows.getChildAt(0).requestFocus();}
 private GradientDrawable background(boolean focus){GradientDrawable g=new GradientDrawable();g.setColor(UiTheme.panel(this));g.setCornerRadius(dp(8));g.setStroke(dp(focus?3:1),focus?UiTheme.accent(this):UiTheme.panel(this));return g;}
 private void resume(VodSource.Title t){selected=t;JSONObject h=VodLibrary.latest(this,"raiplay",t.id);String url=h==null?t.json.optString("_rai_page"):h.optString("episode",t.json.optString("_rai_page"));if(url.isEmpty())url=t.json.optString("_rai_page");detail(url,h==null?t.name:h.optString("label",t.name),true);}
 private void detail(String url,String label,boolean push){if(!RaiPlayAdapter.owns(url)){status.setText("Collegamento RaiPlay non valido");return;}if(push&&!page.isEmpty()&&!page.equals(url))back.push(page+"\n"+pageLabel);cancel();page=url;pageLabel=label;int request=generation;status.setText("Caricamento · "+label);worker.submit(()->{try{JSONObject data=RaiPlayAdapter.data(url);List<RaiPlayAdapter.Entry> entries=RaiPlayAdapter.entries(data);runOnUiThread(()->{if(destroyed||request!=generation)return;if(data.optJSONObject("video")!=null){int index=-1;for(int i=0;i<episodeQueue.length();i++)if(url.equals(episodeQueue.optJSONObject(i).optString("id")))index=i;play(url,label,episodeQueue,index);return;}rows.removeAllViews();if(selected!=null&&!selected.poster.isEmpty()){ProgrammeArtwork hero=new ProgrammeArtwork(this);hero.setScaleType(ImageView.ScaleType.FIT_CENTER);rows.addView(hero,new LinearLayout.LayoutParams(-1,dp(220)));artwork.bind(hero,selected.poster,new ColorDrawable(UiTheme.panel(this)));}rows.addView(text(label,24));String plot=data.optString("description",data.optString("synopsis"));if(!plot.isEmpty())rows.addView(text(android.text.Html.fromHtml(plot,0).toString(),15));JSONArray queue=new JSONArray();for(RaiPlayAdapter.Entry e:entries)if(e.url.contains("/video/"))try{queue.put(new JSONObject().put("id",e.url).put("name",e.title));}catch(Exception ignored){}episodeQueue=queue;for(RaiPlayAdapter.Entry e:entries){long position=VodLibrary.position(this,"raiplay",selected==null?"":selected.id,e.url);Button b=button(e.title+(position>0?" · Riprendi "+VodLibrary.clock(position):""));rows.addView(b,new LinearLayout.LayoutParams(-1,dp(60)));b.setOnClickListener(v->detail(e.url,e.title,true));}status.setText(entries.isEmpty()?"Nessun episodio disponibile":"Scegli una stagione o un episodio");if(rows.getChildCount()>1)rows.getChildAt(1).requestFocus();});}catch(Exception e){runOnUiThread(()->{if(!destroyed&&request==generation)status.setText(e.getMessage());});}});}
 private void play(String url,String label,JSONArray queue,int index){if(selected==null)return;if(!RaiAccount.active()){status.setText("Accedi a RaiPlay per riprodurre questo contenuto");startActivity(new Intent(this,RaiAccountActivity.class));return;}startActivity(new Intent(this,VodPlayerActivity.class).putExtra("source",RaiLibrary.source().json().toString()).putExtra("titleJson",selected.json.toString()).putExtra("episode",url).putExtra("label",label).putExtra("episodes",queue.toString()).putExtra("index",index));status.setText(label);}
 public void onBackPressed(){if(!back.isEmpty()){String[] entry=back.pop().split("\n",2);detail(entry[0],entry.length>1?entry[1]:"RaiPlay",false);}else if(!page.isEmpty()){page="";loadCatalogue();}else finish();}
 protected void onResume(){super.onResume();if(rows!=null&&history&&page.isEmpty())loadCatalogue();}
 protected void onSaveInstanceState(Bundle s){s.putString("queue",episodeQueue.toString());s.putBoolean("history",history);s.putString("query",query.getText().toString());s.putString("page",page);s.putString("label",pageLabel);s.putStringArrayList("back",new ArrayList<>(back));if(selected!=null)s.putString("title",selected.json.toString());super.onSaveInstanceState(s);}
 protected void onDestroy(){destroyed=true;cancel();worker.shutdownNow();artwork.close();super.onDestroy();}
}
